ALTER TABLE bridge_pending_events ADD COLUMN workspace_role TEXT NOT NULL DEFAULT 'source' CHECK (workspace_role IN ('source', 'destination'));
ALTER TABLE bridge_pending_events ADD COLUMN mutation_id TEXT;
CREATE TABLE IF NOT EXISTS bridge_mutations (mutation_id TEXT PRIMARY KEY NOT NULL, projection_key TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('pending', 'applied')), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS bridge_field_revisions (field_key TEXT PRIMARY KEY NOT NULL, destination_key TEXT NOT NULL, source_workspace_key TEXT NOT NULL, object_name TEXT NOT NULL, record_id TEXT NOT NULL, field_name TEXT NOT NULL, revision INTEGER NOT NULL, last_event_timestamp TEXT NOT NULL, last_workspace_role TEXT NOT NULL CHECK (last_workspace_role IN ('source', 'destination')), last_mutation_id TEXT NOT NULL, value_json TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS bridge_conflicts (conflict_key TEXT PRIMARY KEY NOT NULL, field_key TEXT NOT NULL, event_id TEXT NOT NULL, existing_mutation_id TEXT NOT NULL, incoming_value_json TEXT NOT NULL, existing_value_json TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('blocked', 'resolved')), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS bridge_note_shares (share_key TEXT PRIMARY KEY NOT NULL, source_workspace_key TEXT NOT NULL, source_record_id TEXT NOT NULL, destination_key TEXT NOT NULL, mutation_id TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('pending', 'projected', 'blocked')), created_at TEXT NOT NULL);
